mapper.select:
SELECT b.*, u.real_name AS technician_name
FROM biz_booking b
LEFT JOIN sys_user u ON b.technician_id = u.id
WHERE b.user_id = #{userId}

    AND b.status = #{status}

ORDER BY b.create_time DESC

SELECT b.id, b.booking_no, b.user_id, b.vehicle_id, b.booking_date, b.time_slot, b.estimated_price, b.technician_id, CAST(b.status AS SIGNED) as status, b.remark, b.create_time, b.update_time, customer.real_name AS customer_name, COALESCE(tech.real_name, tech2.real_name) AS technician_name FROM biz_booking b LEFT JOIN sys_user customer ON b.user_id = customer.id LEFT JOIN sys_user tech ON b.technician_id = tech.id LEFT JOIN biz_repair_order o ON b.id = o.booking_id LEFT JOIN sys_user tech2 ON o.technician_id = tech2.id WHERE 1=1
AND b.status = #{status}
AND b.booking_date = #{date}
ORDER BY b.create_time DESC
